const categoryOpenGroups=new Set();
document.addEventListener('toggle',e=>{const el=e.target;if(!el.isConnected||!el.matches?.('details[data-category-disclosure]'))return;const cid=el.dataset.categoryDisclosure;if(el.open)categoryOpenGroups.add(cid);else categoryOpenGroups.delete(cid);},true);
const libraryFilters=new Map();

// Header tools remain ordinary buttons and links inside a keyboard-accessible disclosure.
document.addEventListener('click',e=>{const menu=document.getElementById('deskTools');if(menu?.open&&(!menu.contains(e.target)||e.target.closest('.desk-tools-menu button,.desk-tools-menu a')))menu.open=false;});
document.addEventListener('keydown',e=>{const menu=document.getElementById('deskTools');if(e.key==='Escape'&&menu?.open){menu.open=false;menu.querySelector('summary').focus();e.preventDefault();}});
const libraryOpenCharacters=new Set();
document.addEventListener('toggle',e=>{const el=e.target;if(!el.isConnected||!el.matches?.('details[data-library-character]'))return;if(el.open)libraryOpenCharacters.add(el.dataset.libraryCharacter);else libraryOpenCharacters.delete(el.dataset.libraryCharacter);},true);
function revealCharacterLibrary(){const el=document.getElementById('character-library');if(!el)return;libraryOpenCharacters.add(el.dataset.libraryCharacter);el.open=true;el.scrollIntoView({block:'start'});}

const libraryOpenGroups=new Set();
document.addEventListener('toggle',e=>{const el=e.target;if(!el.isConnected||!el.matches?.('details[data-library-disclosure]'))return;const key=el.dataset.libraryDisclosure;if(el.open)libraryOpenGroups.add(key);else libraryOpenGroups.delete(key);},true);
function characterReviewInventory(c){
 const list=[...new Set(c.candidate_ids)].map(id=>assets.get(id)).filter(Boolean),active=list.filter(a=>effectiveStatus(a)!=='Obsolete');
 const approved=new Set(approvedReferences(c.id).filter(r=>knownSourceHash(assets.get(r.id),r.source_sha256)).map(r=>r.id+':'+r.source_sha256));
 return {list,active,approved};
}
function characterImageCounts(c){
 const {list,active,approved}=characterReviewInventory(c);
 return {total:list.length,active:active.length,pending:active.filter(a=>!approved.has(a.id+':'+a.sha256)).length,obsolete:list.length-active.length};
}
function personReviewChips(c){
 const {active,approved}=characterReviewInventory(c),groups=new Map();
 // Count each image once, using its character-specific category when supplied.
 for(const a of active){const type=(a.reference_links||[]).find(r=>r.character_id===c.id)?.type||a.type;const group=groups.get(type)||{total:0,pending:0};group.total++;if(!approved.has(a.id+':'+a.sha256))group.pending++;groups.set(type,group);}
 const labels={'Portrait / likeness':'Likeness','Full-body / costume':'Body','Emotion map':'Map','Individual emotion':'Emotion','Scene reference':'Scene','Supporting prop / map':'Props','Mannequin outfit study':'Outfit','Hairstyle study':'Hair'};
 const categories=[...new Set([...types.slice(0,4),...groups.keys()])];
 return `<div class="chips person-review-chips" aria-label="Images by category and review status">${categories.map(type=>{const {total=0,pending=0}=groups.get(type)||{},done=total-pending,state=pending?'pending':total?'approved':'missing',description=total?`${type}: ${done} approved, ${pending} awaiting review`:`${type}: no active images`;return `<button type="button" class="chip ${state}" data-character-category="${esc(type)}" data-category-character="${esc(c.id)}" title="Open ${esc(type)} · ${esc(c.name)}" aria-label="Open ${esc(type)} for ${esc(c.name)} — ${esc(description)}"><span>${esc(labels[type]||type)}</span><strong>${pending?pending+' to review':total?'✓ '+done+' approved':'No images'}</strong>${pending&&done?`<small>${done} approved</small>`:''}</button>`;}).join('')}</div>`;
}
function openCharacterCategory(cid,type){
 if(!people.has(cid)||!types.includes(type))return;
 // A category shortcut should reveal its images even when roster filters were active.
 for(const key of ['search','type','status'])$(key).value='';
 const categoryKey=JSON.stringify([cid,type]),libraryKey=JSON.stringify([cid,'type',type]);
 categoryOpenGroups.add(categoryKey);
 if(people.get(cid)?.library_view===true&&type!=='Individual emotion'){
  libraryFilters.set(cid,{act:'',song:'',status:'active',group:'type',jumpType:type});
  libraryOpenCharacters.add(cid);libraryOpenGroups.add(libraryKey);
 }
 detail(cid);
 const target=[...document.querySelectorAll('[data-category-disclosure]')].find(el=>el.dataset.categoryDisclosure===categoryKey)||[...document.querySelectorAll('[data-library-disclosure]')].find(el=>el.dataset.libraryDisclosure===libraryKey);
 if(!target)return;
 target.open=true;
 requestAnimationFrame(()=>{
  if(!target.isConnected)return;
  const header=document.querySelector('body>header'),position=header&&getComputedStyle(header).position;
  const offset=(position==='sticky'||position==='fixed'?header.getBoundingClientRect().height:0)+16;
  target.querySelector('summary')?.focus({preventScroll:true});
  window.scrollTo({top:window.scrollY+target.getBoundingClientRect().top-offset,behavior:'instant'});
 });
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-character-category]');if(b)openCharacterCategory(b.dataset.categoryCharacter,b.dataset.characterCategory);});
function songUses(a){return a.song_appearances?.length?a.song_appearances:[{song:'Unassigned / character references',act:'Unassigned'}];}
function characterLibrary(c){
 const f=libraryFilters.get(c.id)||{act:'',song:'',status:'',group:'song'},all=[...new Set(c.candidate_ids)].map(id=>assets.get(id)).filter(Boolean),counts=characterImageCounts(c);
 const uses=all.flatMap(songUses),acts=[...new Set(uses.map(x=>x.act||'Unassigned'))].sort(),songs=[...new Set(uses.filter(x=>!f.act||(x.act||'Unassigned')===f.act).map(x=>x.song))].sort();
 const matches=a=>(!f.act||songUses(a).some(x=>(x.act||'Unassigned')===f.act&&(!f.song||x.song===f.song)))&&(!f.song||songUses(a).some(x=>x.song===f.song))&&(!f.status||f.status==='active'&&effectiveStatus(a)!=='Obsolete'||f.status==='pending'&&referenceStatus(a,c.id)==='Needs review'||f.status==='approved'&&referenceStatus(a,c.id)==='Approved reference'||f.status==='obsolete'&&effectiveStatus(a)==='Obsolete');
 const list=all.filter(matches),groups=new Map();
 for(const a of list){const labels=f.group==='type'?[(a.reference_links||[]).find(r=>r.character_id===c.id)?.type||a.type]:[...new Set(songUses(a).filter(x=>(!f.act||(x.act||'Unassigned')===f.act)&&(!f.song||x.song===f.song)).map(x=>x.song))];for(const label of labels){if(!groups.has(label))groups.set(label,[]);groups.get(label).push(a);}}
 if(f.group==='type'&&types.includes(f.jumpType)&&!groups.has(f.jumpType))groups.set(f.jumpType,[]);
 const options=(vals,selected)=>vals.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('');
 return `<details class="character-library" id="character-library" data-library-character="${esc(c.id)}"${libraryOpenCharacters.has(c.id)?' open':''} aria-labelledby="character-library-heading"><summary class="library-summary"><h2 id="character-library-heading">${esc(c.name)} · Image library</h2><span class="library-summary-count">${counts.total} image${counts.total===1?'':'s'}</span></summary><div class="library-body"><p><strong>${counts.total} indexed images</strong> · ${counts.pending} awaiting review · ${counts.obsolete} set aside</p><div class="library-filters"><label>Act<select aria-label="Act" data-library-filter="act"><option value="">All Acts</option>${options(acts,f.act)}</select></label><label>Song<select aria-label="Song" data-library-filter="song"><option value="">All songs</option>${options(songs,f.song)}</select></label><label>Review status<select aria-label="Review status" data-library-filter="status"><option value="">All images</option>${[['active','Active'],['pending','Awaiting review'],['approved','Approved'],['obsolete','Set aside']].map(([v,l])=>`<option value="${v}" ${f.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Group by<select aria-label="Group by" data-library-filter="group">${[['song','Song'],['type','Reference type']].map(([v,l])=>`<option value="${v}" ${f.group===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="library-help-tools"><div class="library-filter-help"><button type="button" class="library-help-icon" aria-label="About image counts" aria-describedby="library-count-help"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M9 18h6M9 21h6M8 14a6 6 0 1 1 8 0c-1 .8-1 1.5-1 2H9c0-.5 0-1.2-1-2Z"/></svg></button><div class="library-help-tooltip" id="library-count-help" role="tooltip"><ul><li>${list.length} distinct images match these filters${groups.size>1?' across '+groups.size+' groups':''}.</li><li>An image used in more than one song appears in each group and counts once.</li></ul></div></div><details class="library-index-note"><summary class="library-help-icon" title="Index coverage &amp; sources" aria-label="Index coverage &amp; sources"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/></svg><span class="library-help-chevron" aria-hidden="true">▸</span></summary><p>Images are linked from source filenames, cast lists and shot descriptions. New imports remain unapproved. Unassigned means the source does not identify a song or Act; it is not a guess.</p><p>${esc(c.image_library_audit?.summary||'')}</p>${c.image_library_audit?.snapshot?`<a href="${esc(c.image_library_audit.snapshot)}" target="_blank">Open source inventory</a>`:``}</details></div><h3 class="library-groups-subtitle">${f.group==='song'?'Musical numbers':'Reference types'}</h3>${[...groups].sort(([a],[b])=>a.localeCompare(b)).map(([label,aa])=>{const k='library:'+c.id+':'+label,more=expanded.has(k),disclosureKey=JSON.stringify([c.id,f.group,label]);return `<details class="library-song" data-library-disclosure="${esc(disclosureKey)}"${libraryOpenGroups.has(disclosureKey)?' open':''}><summary class="library-group-summary"><h3>${esc(label)}</h3><span class="library-group-count">${aa.length} image${aa.length===1?'':'s'}</span></summary><div class="library-group-body">${f.group==='type'&&label==='Hairstyle study'?`<p><button type="button" data-hairstyle-bulk="${esc(c.id)}">Approve all hairstyles…</button></p>`:''}${f.group==='song'?`<p class="small">${esc([...new Set(aa.flatMap(songUses).filter(x=>x.song===label).map(x=>x.act||'Unassigned'))].join(' · '))}</p>`:''}<div class="assetgrid">${aa.slice(0,more?aa.length:24).map(a=>assetCard(a)).join('')||'<p class="sectiongap">No active images in this category yet.</p>'}</div>${aa.length>24&&!more?`<button data-library-more="${esc(k)}">Show all ${aa.length} images in ${esc(label)}</button>`:''}</div></details>`}).join('')||'<p class="sectiongap">No images match these filters.</p>'}</div></details>`;
}
document.addEventListener('change',e=>{const field=e.target.dataset.libraryFilter;if(!field||!current)return;const f={act:'',song:'',status:'',group:'song',...libraryFilters.get(current),[field]:e.target.value};if(field==='act')f.song='';libraryFilters.set(current,f);libraryOpenCharacters.add(current);const focus=field;detail(current);document.querySelector(`[data-library-filter="${focus}"]`)?.focus();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.libraryMore){expanded.add(b.dataset.libraryMore);const y=window.scrollY;detail(current);window.scrollTo(0,y);}if(b?.hasAttribute('data-library-jump'))revealCharacterLibrary();});

// Action colors use full category data, independent of display filters.
function sectionActionRollup(states){return states.includes('images')?'images':states.includes('selection')?'selection':'ready';}
function sectionActionModel(c){
 const all=[...new Set(c.candidate_ids)].map(id=>assets.get(id)).filter(Boolean);
 const active=list=>list.filter(a=>a&&effectiveStatus(a)!=='Obsolete');
 const selected=Object.values(canonCurrent(c.id)).filter(r=>{const a=assets.get(r.id);return a&&a.character_ids.includes(c.id)&&effectiveStatus(a)!=='Obsolete'&&knownSourceHash(a,r.source_sha256);});
 const approved=approvedReferences(c.id);
 const imageState=(list,role=null)=>{const available=active(list);if(!available.length)return 'images';return available.some(a=>selected.some(r=>r.id===a.id&&(!role||canonRoleFamily(r.role)===role))||approved.some(r=>r.id===a.id&&r.source_sha256===a.sha256&&(!role||canonRoleFamily(r.role)===role)))?'ready':'selection';};
 const roles=['likeness','body','emotion'].map(role=>selected.some(r=>canonRoleFamily(r.role)===role)?'ready':active(all).some(a=>canonAllowed(a,role))?'selection':'images');
 const categories=new Map(types.map(type=>[type,imageState(all.filter(a=>assetInCategory(a,c.id,type)))]));
 categories.set('Individual emotion',emotionCoverage(c).state);
 const coverage=coverageCategories.map(category=>category.key==='individual_emotion'?emotionCoverage(c).state:imageState(coverageItems(c,category.key,true),category.role));
 const looks=new Map((c.looks||[]).filter(l=>l.active_story!==false).map(l=>[l.id,selected.some(r=>r.role==='body'&&r.look_id===l.id)?'ready':lookBodyCandidates(c,l).length?'selection':'images']));
 return {selected:sectionActionRollup(roles),coverage:sectionActionRollup(coverage),wardrobe:sectionActionRollup([...looks.values()]),categories,looks,imageState,all};
}
const sectionActionLabels={ready:'No action needed',selection:'Selections needed',images:'Images needed'};
function sectionColorLegend(){
 const entries=[['ready','Green','✓'],['selection','Amber','!'],['images','Purple','+']];
 return `<details class="section-status-legend"><summary aria-label="Section color legend" title="Section colors"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M9 18h6M10 21h4M8.5 14.5a6 6 0 1 1 7 0c-.9.7-1.5 1.8-1.5 3h-4c0-1.2-.6-2.3-1.5-3Z"/></svg></summary><div class="section-status-legend-body"><strong>Section colors</strong><div class="section-status-keys">${entries.map(([state,color,symbol])=>`<span class="section-status-key" data-action-state="${state}"><span aria-hidden="true">${symbol}</span> ${color} · ${sectionActionLabels[state]}</span>`).join('')}</div><p>Colors show what each section needs. Green does not mean every image has been reviewed.</p></div></details>`;
}
function applySectionActionStates(c){
 const root=$('content');if(!root||!c)return;
 const model=sectionActionModel(c),labels=sectionActionLabels;
 function mark(el,state){if(!el)return;el.classList.add('action-section');el.dataset.actionState=state;const summary=el.querySelector(':scope > summary');if(summary){summary.title=labels[state];let text=summary.querySelector(':scope > .section-action-accessible');if(!text){text=document.createElement('span');text.className='save-sr-only section-action-accessible';summary.append(text);}text.textContent=' · '+labels[state];}}
 mark(root.querySelector('.canonpanel'),model.selected);
 mark(root.querySelector('.reference-review-section'),model.coverage);
 mark(root.querySelector('.costume-looks-section'),model.wardrobe);
 mark(root.querySelector('.wardrobe-disclosure'),model.wardrobe);
 mark(root.querySelector('.add-references'),model.coverage);
 for(const el of root.querySelectorAll('[data-category-disclosure]')){const [,type]=JSON.parse(el.dataset.categoryDisclosure);mark(el,model.categories.get(type));}
 for(const el of root.querySelectorAll('.lookcard'))mark(el,model.looks.get(el.id.slice(5))||'ready');
 for(const el of root.querySelectorAll('[data-library-disclosure]')){const [,group,label]=JSON.parse(el.dataset.libraryDisclosure);mark(el,model.imageState(model.all.filter(a=>group==='type'?a.type===label:songUses(a).some(x=>x.song===label))));}
 // Archived material and informational disclosures carry no required action.
 const songs=[...new Set(model.all.flatMap(songUses).map(use=>use.song))];
 mark(root.querySelector('#character-library'),songs.length?sectionActionRollup(songs.map(song=>model.imageState(model.all.filter(a=>songUses(a).some(use=>use.song===song))))):model.imageState(model.all));
 for(const el of root.querySelectorAll('.obsoleteSection'))mark(el,'ready');
 for(const el of root.querySelectorAll('.sourcecollection')){const ids=[...el.querySelectorAll('[data-image]')].map(b=>b.dataset.image);mark(el,model.imageState(ids.map(id=>assets.get(id)).filter(Boolean)));}
}
window.addEventListener('desk-approval-saved',()=>{if(current&&people.has(current)){applySectionActionStates(people.get(current));window.DESKSectionOrder?.refresh();}});

function rosterDateReadout(c){
 const note=(c.age_note||'Age not recorded.').trim();
 const match=note.match(/^(?:Source roster age|Script age|User-specified design age):\s*(\d+)(?:\s*\([^)]*\))?\.?$/i);
 const age=match?Number(match[1]):null;const year=D.project?.story_year;
 return {age:age===null?'Unknown':String(age),note,birth:age===null||!Number.isInteger(year)?'Unknown':`${year-1-age}–${year-age}`,birthNote:Number.isInteger(year)?`Estimated from the recorded age in ${year}; exact birthdate is not recorded.`:'Set project.story_year to estimate birth years from character ages.'};
}
function characterFacts(c){
 const d=rosterDateReadout(c);
 const help=(label,note)=>`<details class="profile-fact-help"><summary aria-label="${esc(label)}" title="${esc(note)}"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/></svg></summary><div class="profile-fact-note">${esc(note)}</div></details>`;
 return `<dl class="profile-facts" aria-label="Roster details"><div class="profile-fact-age"><dt>Age at story time</dt><dd><span>${esc(d.age)}</span>${help('About age at story time',d.note)}</dd></div><div class="profile-fact-birth"><dt>Birthdate <span class="profile-estimate">(estimated)</span></dt><dd><span>${esc(d.birth)}</span>${help('About the estimated birthdate',d.birthNote)}</dd></div><div class="profile-fact-aliases"><dt>Also known as</dt><dd>${esc(c.aliases.length?c.aliases.join(' · '):'No aliases recorded')}</dd></div></dl>`;
}

function detail(cid){window.DESKLocations?.deactivate();updateApprovedTotal();const c=people.get(cid);if(!c)return;current=cid;document.querySelector('.intro').hidden=true;$('results').textContent='';const s=state(),all=c.candidate_ids.map(id=>assets.get(id)),aa=all.filter(a=>assetMatches(a,s));let pair=review.pairs[cid]||{};let h=`<div class="character-actions"><details class="reference-icon-details record-help"><summary aria-label="About character records" title="About character records"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/></svg></summary><div class="reference-details-body">Character record · IDs stay stable when files are moved or copied</div></details><button class="character-export" type="button" data-export-character="${esc(cid)}" aria-label="Export options" title="Export options"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 16V3m-4 4 4-4 4 4M5 12v8a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-8"/></svg></button></div><section class="detailhead"><div class="detail-overview"><div class="character-profile">${characterSeasonBand(c)}<button type="button" class="eyebrow character-family-back" data-group="${esc(c.group)}" data-family-return aria-label="Back to ${esc(D.groups.find(g=>g.id===c.group)?.label)}" title="Back to family view"><span aria-hidden="true">←</span> ${esc(D.groups.find(g=>g.id===c.group)?.label)}</button><h1>${esc(c.name)}</h1>${characterIntro(c)}${characterFacts(c)}</div><div class="character-overview-side">${characterReviewSummary(c)}${characterPortrait(c)}</div></div></section>${window.DESKExploration?.entry(c)||''}${sectionColorLegend()}${canonPanel(c)}${featuredReferences(c)}${looksView(c)}`;
if(c.library_view===true){h+=`<details class="assetgroup add-references"><summary class="add-references-summary"><h2>Add References</h2></summary><div class="add-references-body">${types.map(t=>`<p>${esc(t)} <button data-add-reference="${esc(t)}" data-add-character="${esc(cid)}">+ Add reference</button></p>`).join('')}</div></details>`+emotionSlotsView(c)+characterLibrary(c);}else{for(const t of types){if(t==='Individual emotion'&&(!s.type||s.type===t)){h+=emotionSlotsView(c);continue;}if(t==='Hairstyle study'&&!all.some(a=>assetInCategory(a,cid,t)))continue;if(s.type&&t!==s.type)continue;const ar=aa.filter(a=>assetInCategory(a,cid,t)).filter(a=>effectiveStatus(a)!=='Obsolete').sort(rankOrder);h+=`${['Portrait / likeness','Full-body / costume','Emotion map','Individual emotion','Scene reference','Supporting prop / map','Mannequin outfit study','Hairstyle study'].includes(t)?`<details class="assetgroup category-references" data-category-disclosure="${esc(JSON.stringify([cid,t]))}"${categoryOpenGroups.has(JSON.stringify([cid,t]))?' open':''}><summary class="category-references-summary"><h2>${t==='Portrait / likeness'?'Portrait &amp; Likeness':t==='Hairstyle study'?'Hairstyles':t==='Scene reference'?'Scene References':esc(t)}</h2><span class="category-reference-count">${ar.length} image${ar.length===1?'':'s'}</span></summary><div class="category-references-body">`:`<section class="assetgroup"><h2>${esc(t)} <small class="small">${ar.length}</small></h2>`}<div class="category-icon-actions" role="group" aria-label="${esc(t)} category actions">${t==='Hairstyle study'?`<button type="button" data-hairstyle-bulk="${esc(cid)}">Approve all…</button>`:''}${assetIconButton('add','Add reference',`data-add-reference="${esc(t)}" data-add-character="${esc(cid)}"`)}${all.some(a=>assetInCategory(a,cid,t)&&effectiveStatus(a)!=='Obsolete')?assetIconButton('rank','Rank / reorder complete category',`data-rank-group="${esc(t)}" data-rank-character="${esc(cid)}"`):''}</div>`;if(t==='Supporting prop / map'&&window.DESKProps){h+=window.DESKProps.render(c,ar);h+='</div></details>';continue;}if(t==='Scene reference')h+=sceneReferenceCollections(c);if(ar.length){const more=expanded.has(cid+t);h+=`<div class="assetgrid">${(more?ar:ar.slice(0,8)).map(assetCard).join('')}</div>`;if(ar.length>8&&!more)h+=`<p><button data-expand="${esc(t)}">Show all ${ar.length} ${esc(t.toLowerCase())} references</button></p>`;}else h+=`<div class="sectiongap">${all.some(a=>assetInCategory(a,cid,t))?'No images in this category match the active status filter.':'Missing — no reference in this category has been correlated.'}</div>`;h+=['Portrait / likeness','Full-body / costume','Emotion map','Individual emotion','Scene reference','Supporting prop / map','Mannequin outfit study','Hairstyle study'].includes(t)?'</div></details>':'</section>';}const obsolete=all.filter(a=>effectiveStatus(a)==='Obsolete'&&(!s.type||assetInCategory(a,cid,s.type))).sort(rankOrder);if(obsolete.length){h+=`<details class="obsoleteSection"><summary>Obsolete · ${obsolete.length} images — expand to inspect or restore</summary><p class="small">Files are preserved. Source obsolescence and your local choices are shown separately. Restore returns an image to active candidates without conferring canon approval.</p>${types.map(t=>{const items=obsolete.filter(a=>assetInCategory(a,cid,t));return items.length?`<h2>${esc(t)}</h2><div class="assetgrid">${items.map(assetCard).join('')}</div>`:'';}).join('')}</details>`;}}$('content').innerHTML=h;applySectionActionStates(c);$('characterTools').replaceChildren(document.querySelector('#content>.character-actions'));window.DESKSectionOrder?.mount(cid);}
