 openModal('Image review · '+a.type,`<div class="image-review-layout"><section class="image-review-preview"><div class="image-review-image"><img class="fullasset" src="${esc(a.asset)}" alt="${esc(a.title)}"><div class="image-review-overlay">${cid?`<button type="button" id="imageReviewChange" class="image-review-icon" aria-label="Change image" title="Change image · Browse all images tagged with ${esc(people.get(cid)?.name||cid)}"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="14" height="14" rx="2"/><circle cx="7.5" cy="7.5" r="1"/><path d="m3 13 4-4 5 5 3-3M9 21h12V9M17 19l2 2-2 2"/></svg></button>`:'<span></span>'}<button type="button" id="imageReviewInfo" class="image-review-icon" aria-label="Image technical specs" title="Image technical specs" aria-controls="imageTechnicalDetails" aria-expanded="false"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v.1"/></svg></button></div></div><a class="small" href="${esc(a.asset)}" target="_blank" rel="noopener">Open full-size image ↗</a></section><section class="reviewform image-review-controls"><h2>Review</h2>${reviewLocation?DESKLocationImageReview.controls(a,reviewLocation):reviewReferenceIcons(a,cid,context)}<label>Preference<select id="verdict"><option>Unreviewed</option><option>Prefer</option><option>Reject</option></select></label><label>Notes<textarea id="note" maxlength="20000" placeholder="What works, what needs changing…">${esc(n.text)}</textarea></label><div class="image-review-update"><button type="button" id="updateImageReview" title="Save this image’s preference and notes now">${reviewLocation?'Save notes':'Update'}</button><span id="imageReviewSaveStatus" class="small" role="status" aria-live="polite"></span></div><div class="image-review-secondary"><span>Rank: ${esc(rankValue(a,cid)??'Unranked')}</span>${cid&&effectiveStatus(a)!=='Obsolete'?`<button data-rank-group="${esc(a.type)}" data-rank-character="${esc(cid)}">Change rank</button>`:''}<button id="modalObsolete">${effectiveStatus(a)==='Obsolete'?'Restore image':'Set aside'}</button></div><details><summary>More review options</summary><label>Suggested use (does not select a reference)<input id="proposedRole" value="${esc(n.role||'')}" placeholder="e.g. hair or winter costume"></label></details></section></div><details class="image-technical-details" id="imageTechnicalDetails"><summary>Technical details</summary><button type="button" id="imageSpecsBack">Back to image</button><p><strong>Image ID:</strong> <code>${esc(a.id)}</code><br><strong>Filename:</strong> ${esc(a.title)}<br><strong>Dimensions:</strong> ${a.width||'Unknown'} × ${a.height||'Unknown'} pixels<br><strong>Format:</strong> ${esc((a.asset.split('.').pop()||'Unknown').toUpperCase())}<br><strong>Megapixels:</strong> ${a.width&&a.height?(a.width*a.height/1000000).toFixed(2):'Unknown'}<br><strong>Story stage:</strong> ${esc(a.stage)}</p><p>Source status: ${esc(a.status)}. ${esc(a.approval)}</p><p>${esc(a.usage_note||'Review age, identity and story stage before use.')}</p><p>${esc(a.identity_basis)} ${esc(a.interpretation||'')} ${esc(a.variant_note||'')} ${esc(a.visual_description||'')} ${esc(a.scope_note||'')}</p><h3>Source paths & provenance</h3>${a.sources.map(path=>`<p class="path">${esc(path)}</p>`).join('')}<p class="path">SHA-256: ${esc(a.sha256)}</p>${a.metadata_sources.map(path=>`<p><a href="${esc(path)}" target="_blank">Source metadata</a></p>`).join('')}<p class="small">${esc(a.asset_encoding)} ${esc(a.archive_note||'')}</p>${a.previous_versions?.length?`<details><summary>Previous image versions (${a.previous_versions.length})</summary><p>Earlier selections stay tied to their exact image version.</p>${a.previous_versions.map(v=>`<p><a href="${esc(v.asset)}" target="_blank">${esc(v.label||'Previous image')}</a> · <a href="${esc(v.record)}">Provenance</a><br><small>${esc(v.sha256)}</small></p>`).join('')}</details>`:''}${originalPromptView(a)}</details>`);
 if(reviewLocation)DESKLocationImageReview.bind(a,reviewLocation);
 if(context.selectionLook&&people.get(context.selectionCharacter)?.looks?.some(l=>l.id===context.selectionLook))$('modalBody').insertAdjacentHTML('afterbegin',`<p><button data-wardrobe-browse="${esc(context.selectionLook)}" data-wardrobe-character="${esc(context.selectionCharacter)}">Browse all tagged images for this look</button></p>`);
 const info=$('imageReviewInfo'),specs=$('imageTechnicalDetails');
 info.onclick=()=>{specs.open=!specs.open;info.setAttribute('aria-expanded',String(specs.open));if(specs.open){specs.scrollIntoView({block:'start'});specs.querySelector('summary').focus();}};
 specs.addEventListener('toggle',()=>info.setAttribute('aria-expanded',String(specs.open)));
 $('imageSpecsBack').onclick=()=>{specs.open=false;info.scrollIntoView({block:'center'});info.focus();};
 if($('imageReviewChange'))$('imageReviewChange').onclick=()=>imageReviewGallery(cid,id,context);
 $('verdict').value=n.verdict;
 const fields={verdict:$('verdict'),text:$('note'),role:$('proposedRole')},update=$('updateImageReview'),feedback=$('imageReviewSaveStatus');
 const values=()=>Object.fromEntries(Object.entries(fields).map(([key,el])=>[key,el.value]));
 const matches=(a,b)=>['verdict','text','role'].every(k=>(a?.[k]||(k==='verdict'?'Unreviewed':''))===(b?.[k]||(k==='verdict'?'Unreviewed':'')));
 const commitNote=()=>{const next=values();if(matches(next,review.notes[id]))return;review.notes[id]={...review.notes[id],...next,updated_at:new Date().toISOString()};feedback.textContent='Changes waiting to save…';save();};
 // Capture both input and change so native selects and keyboard edits use the same path.
 for(const field of Object.values(fields)){field.addEventListener('input',commitNote);field.addEventListener('change',commitNote);}
 const saveStatus=e=>{
  if(!feedback.isConnected)return;
  const status=e.detail;
  if(status.saved&&matches(values(),approvalSource()?.notes?.[id])){feedback.textContent='Saved on this Mac.';feedback.dataset.state='saved';}
  else{feedback.textContent=status.text;feedback.dataset.state=status.busy?'saving':'pending';}
 };
 const bindApproval=()=>{
  const button=$('approveReviewImage');if(!button)return;
  button.onclick=async()=>{
   if(!approveReviewImage(a,cid,context))return;
   button.disabled=true;feedback.textContent='Saving image approval…';feedback.dataset.state='saving';
   try{if(window.DESKAutosave)await window.DESKAutosave.flush();}
   catch(error){feedback.textContent='Could not save approval: '+error.message+'. Click approve to retry.';feedback.dataset.state='pending';}
   finally{refreshApproval();}
  };
 };
 const refreshApproval=()=>{
  if(!feedback.isConnected||reviewLocation)return;
  const tools=$('modalBody').querySelector('.image-review-reference-tools');
  if(tools){tools.outerHTML=reviewReferenceIcons(a,cid,context);bindApproval();}
 };
 bindApproval();window.addEventListener('desk-approval-saved',refreshApproval);
 window.addEventListener('desk-save-status',saveStatus);
 const cleanup=()=>{window.removeEventListener('desk-approval-saved',refreshApproval);window.removeEventListener('desk-save-status',saveStatus);observer.disconnect();$('modal').removeEventListener('close',cleanup);};
 const observer=new MutationObserver(()=>{if(!feedback.isConnected)cleanup();});observer.observe($('modalBody'),{childList:true});$('modal').addEventListener('close',cleanup);
 update.onclick=async()=>{
  commitNote();feedback.textContent='Saving preference and notes…';feedback.dataset.state='saving';
  if(!window.DESKAutosave){feedback.textContent='Saved in this browser only. Reopen the live reference desk to save on this Mac.';return;}
  try{await window.DESKAutosave.flush();}catch(error){feedback.textContent='Could not update: '+error.message+'. Your edits are retained; click Update to retry.';feedback.dataset.state='pending';}
 };

