function pick(a,role){if(a.mannequin_outfit_eligible){toast('A mannequin is a wardrobe study, not a character likeness, body or emotion. Record its wardrobe role in the note.');return;}if(effectiveStatus(a)==='Obsolete'){toast('This source is obsolete for this character. Choose an active candidate.');return;}if(role==='body'&&a.type!=='Full-body / costume'){toast('Choose a full-body / costume reference for this role.');return;}if(role==='emotion'&&!['Individual emotion','Emotion map'].includes(a.type)){toast('Choose an individual emotion or emotion map for this role.');return;}canonDialog(a.id,a.character_ids[0],null,role);}
function toggleCompare(id){if(compare.has(id))compare.delete(id);else{if(compare.size>=4){toast('Compare up to four images at once.');return;}compare.add(id);}updateCompare();document.querySelectorAll('[data-compare]').forEach(b=>{const selected=compare.has(b.dataset.compare);if(b.classList.contains('asset-icon-action')){const label=selected?'Remove from comparison':'Add to comparison';b.setAttribute('aria-label',label);b.title=label;b.dataset.tooltip=label;}else b.textContent=selected?'✓ In compare':'+ Compare';b.setAttribute('aria-pressed',selected);});}
function updateCompare(){$('compareBar').hidden=!compare.size;$('compareCount').textContent=compare.size+' selected';$('compareOpen').disabled=compare.size<2;}
function compareView(){openModal('Side-by-side comparison',`<p class="small">Reference IDs stay with each image. Compare age, face, hair, costume and story stage; use “Review image” to record a choice.</p><div class="comparegrid">${[...compare].map(id=>{let a=assets.get(id);return `<article><h3>${esc(id)} ${referenceBadge(a,null)}</h3><img src="${esc(a.asset)}" alt="${esc(a.title)}"><p>${esc(a.title)}</p><p>${esc(a.stage)}</p><button data-compare-view="${esc(id)}">Review image ${esc(id)}</button></article>`;}).join('')}</div>`);}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reviewView(){const rows=Object.entries(review.notes);openModal('Ratings & choices',`<section class="reviewdesk"><p>Your ratings and reference choices save on this Mac. Exports are copies of those saved decisions.</p><p class="${storageOK?'small':'storagewarn'}">Storage: ${storageOK?'available in this browser':'unavailable — export before closing'} · ${rows.length} image notes · ${Object.keys(review.pairs).length} character pairs</p><div class="actions"><button type="button" data-export-options>Export options…</button></div><table><thead><tr><th>Image ID</th><th>Rank</th><th>Obsolete</th><th>Preference</th><th>Note</th></tr></thead><tbody>${rows.map(([id,n])=>`<tr><td>${esc(id)}</td><td>${esc(n.rank??'Unranked')}</td><td>${n.obsolete===true?'Yes':n.obsolete===false?'Restored':'Source status'}</td><td>${esc(n.verdict)}</td><td>${esc(n.text)}</td></tr>`).join('')||'<tr><td colspan="5">No review notes yet.</td></tr>'}</tbody></table><h3>Character category rankings</h3><p class="small">These positions override legacy image ranks within the named character only.</p><table><thead><tr><th>Character</th><th>Image</th><th>Rank</th></tr></thead><tbody>${Object.entries(review.rankings||{}).flatMap(([cid,items])=>Object.entries(items).map(([id,r])=>`<tr><td>${esc(people.get(cid)?.name)}</td><td>${esc(id)}</td><td>${esc(r.rank??'Unranked')}</td></tr>`)).join('')||'<tr><td colspan="3">No category reorder yet.</td></tr>'}</tbody></table><h3>Imported collection review notes</h3>${Object.entries(review.collection_reviews||{}).map(([id,r])=>`<details><summary>${esc(people.get(id)?.name||id)}</summary>${Object.entries(r.review||{}).map(([k,v])=>`<p><strong>${esc(k)}:</strong> ${esc(v)}</p>`).join('')}</details>`).join('')||'<p class="small">None imported.</p>'}<h3>Chosen scene references</h3><table><thead><tr><th>Character</th><th>Body / costume</th><th>Emotion</th></tr></thead><tbody>${Object.entries(review.pairs).map(([id,p])=>`<tr><td>${esc(people.get(id)?.name)}</td><td>${esc(p.body||'Missing')}</td><td>${esc(p.emotion||'Missing')}</td></tr>`).join('')||'<tr><td colspan="3">No local choices yet.</td></tr>'}</tbody></table><p><a href="selection-schema.json" target="_blank">Shared export schema</a></p><h3>Import selections JSON</h3><p>Paste exported JSON below, or load an export file. A validated import merges by stable ID. Existing local edits are kept when they conflict, unless you select Replace conflicts below. Unknown IDs are skipped and reported. Matching hashes are verified before any changes; an ID/hash conflict rejects the import. New inventory entries keep their current defaults.</p><input id="importFile" type="file" accept="application/json,.json"><label for="importText" class="small">Review JSON</label><textarea id="importText" placeholder="Paste an DESK review export here"></textarea><label><input id="replaceConflicts" type="checkbox"> Replace conflicting local edits with this import</label><div class="actions"><button id="importReview">Import selections JSON</button></div><p id="importResult" role="status"></p></section>`);$('importFile').onchange=async e=>{const f=e.target.files[0];if(f)$('importText').value=await f.text();};$('importReview').onclick=()=>{try{const v=validateImport(JSON.parse($('importText').value));let imported=0,conflicts=0;const replace=$('replaceConflicts').checked;
 for(const [id,n] of Object.entries(v.notes)){const local=review.notes[id];const differs=local&&Object.keys(n).some(k=>k!=='updated_at'&&local[k]!==n[k]);if(differs&&!replace){conflicts++;continue;}review.notes[id]={...local,...n};imported++;}
 for(const [id,p] of Object.entries(v.pairs)){if(review.pairs[id]&&JSON.stringify(review.pairs[id])!==JSON.stringify(p)&&!replace){conflicts++;continue;}review.pairs[id]={...review.pairs[id],...p};}
 review.rankings=review.rankings||{};for(const [cid,items] of Object.entries(v.rankings||{})){review.rankings[cid]=review.rankings[cid]||{};for(const [id,r] of Object.entries(items)){const local=review.rankings[cid][id];if(local&&local.rank!==r.rank&&!replace){conflicts++;continue;}review.rankings[cid][id]=r;}}
 review.collection_reviews=review.collection_reviews||{};for(const [id,r] of Object.entries(v.collection_reviews||{})){if(!review.collection_reviews[id]||replace)review.collection_reviews[id]=r;else if(JSON.stringify(review.collection_reviews[id])!==JSON.stringify(r))conflicts++;}
 conflicts+=canonMergeImport(v,replace);save();$('importResult').textContent=`Imported ${imported} image choices. Kept ${conflicts} local conflicts. ${v.unmatched_imports.length} unknown IDs skipped: ${v.unmatched_imports.join(', ')||'none'}.`;}catch(e){$('importResult').textContent='Import rejected: '+e.message;}};}
function auditView(){openModal('Sources & roster coverage',`<section class="auditblock"><h2>Project coverage</h2><p>${D.characters.length} characters · ${D.groups.length} groups · ${D.assets.length} images · ${(D.locations||[]).length} locations.</p><p>${esc(D.policy.coverage)}</p><h2>Approval rules</h2><p>${esc(D.policy.approval)}</p><h2>Source snapshots</h2><ul>${D.sources.map(s=>`<li><a href="${esc(s.snapshot)}" target="_blank">${esc(s.id)} · open snapshot</a><div class="path">${esc(s.path)}</div></li>`).join('')||'<li>No sources added yet.</li>'}</ul><p><button type="button" data-export-options>Export options…</button></p></section>`);}

function init(){document.title=(D.project?.name||'Library')+' · Reference Desk';const brand=document.querySelector('.brand-canvas');if(brand){brand.replaceChildren(document.createTextNode('Reference Desk'));const sub=document.createElement('small');sub.textContent=window.DESKContext?.name||D.project?.name||'Library';sub.title=sub.textContent;brand.append(sub);}const a=D.audit;$('stats').innerHTML=[[a.season1_entries,'Roster entries'],[D.groups.length,'Family sections'],[a.indexed_unique_images,'Distinct images'],['…','Approved references']].map(([v,l])=>`<div class="stat" ${l==='Approved references'?'title="Distinct approved images; an image used for several roles counts once."':''}><strong ${l==='Approved references'?'id="approvedReferenceCount"':''}>${v}</strong><span>${l}</span></div>`).join('');$('group').innerHTML+= D.groups.map(g=>`<option value="${esc(g.id)}">${esc(g.label)}</option>`).join('');$('families').innerHTML=`<button data-group="">All families <span>${a.season1_entries}</span></button>`+D.groups.filter(g=>D.characters.some(c=>c.group===g.id)).map(g=>`<button data-group="${esc(g.id)}">${esc(g.label)}<span>${D.characters.filter(c=>c.group===g.id).length}</span></button>`).join('');for(const k of ['search','group','type','status','scope'])$(k).addEventListener(k==='search'?'input':'change',()=>render());$('reset').onclick=()=>{for(const k of ['search','group','type','status'])$(k).value='';$('scope').value='Project roster';render();};$('home').onclick=e=>{e.preventDefault();$('reset').click();window.scrollTo(0,0);};$('reviewOpen').onclick=reviewView;$('auditOpen').onclick=auditView;$('looksOpen').onclick=looksAuditView;$('modalClose').onclick=()=>{$('modal').close();if(current)detail(current);else render();};$('modal').addEventListener('cancel',()=>{setTimeout(()=>current?detail(current):render(),0);});$('compareOpen').onclick=compareView;$('compareClear').onclick=()=>{compare.clear();updateCompare();current?detail(current):render();};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-group')){if(b.hasAttribute('data-family-return'))for(const key of ['search','type','status'])$(key).value='';$('group').value=b.dataset.group;if(['earlier','mentioned'].includes(b.dataset.group))$('scope').value=b.dataset.group==='earlier'?'Earlier draft':'Mentioned only';else if($('scope').value!=='Project roster')$('scope').value='Project roster';render();window.scrollTo(0,0);}if(b.dataset.copyTextarea){copyPlainText(b.dataset.copyTextarea);}if(b.dataset.auditCharacter){$('modal').close();detail(b.dataset.auditCharacter);revealCharacterReferences(b.dataset.auditCharacter);}if(b.dataset.rankGroup){rankingView(b.dataset.rankCharacter,b.dataset.rankGroup);}if(b.dataset.rankMove){const list=groupImages(rankingContext.cid,rankingContext.type),i=list.findIndex(a=>a.id===b.dataset.rankMove);moveRank(b.dataset.rankMove,i+1+(b.dataset.direction==='up'?-1:1),b.dataset.direction);}if(b.dataset.character){detail(b.dataset.character);window.scrollTo(0,0);}if(b.hasAttribute('data-back'))render();if(b.dataset.image)imageView(b.dataset.image,b.dataset);if(b.dataset.compare)toggleCompare(b.dataset.compare);if(b.dataset.expand){expanded.add(current+b.dataset.expand);detail(current);}if(b.dataset.exportCharacter){exportOptions();}if(b.dataset.obsolete){setObsolete(b.dataset.obsolete,b.dataset.value==='true');refreshView();}if(b.dataset.compareView){$('modal').close();imageView(b.dataset.compareView);}});document.addEventListener('change',e=>{if(e.target.dataset.rankSelect)moveRank(e.target.dataset.rankSelect,e.target.value===''?null:Number(e.target.value));});
 document.addEventListener('dragstart',e=>{const h=e.target.closest('[data-drag-rank]');if(!h||!rankingContext)return;draggedRank={id:h.dataset.dragRank,...rankingContext};e.dataTransfer?.setData('text/plain',h.dataset.dragRank);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';h.closest('.rankrow').classList.add('dragging');});
 document.addEventListener('dragover',e=>{const row=e.target.closest('[data-rank-row]');if(row&&draggedRank&&draggedRank.cid===rankingContext?.cid&&draggedRank.type===rankingContext?.type){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));row.classList.add('drop-target');}});
 document.addEventListener('drop',e=>{const row=e.target.closest('[data-rank-row]');if(!row||!draggedRank||draggedRank.cid!==rankingContext?.cid||draggedRank.type!==rankingContext?.type)return;e.preventDefault();const list=groupImages(rankingContext.cid,rankingContext.type),position=list.findIndex(a=>a.id===row.dataset.rankRow)+1;if(position)moveRank(draggedRank.id,position);draggedRank=null;});
 document.addEventListener('dragend',()=>{draggedRank=null;document.querySelectorAll('.dragging,.drop-target').forEach(x=>x.classList.remove('dragging','drop-target'));});
 render();}
init();
